@Component
class EstoqueListener {
    @KafkaListener(topics = "pedidos.criados", groupId = "estoque")
    void aoCriarPedido(PedidoCriado evento) {
        if (processados.existsById(evento.eventoId())) return; // idempotência
        estoque.reservar(evento.itens());
        processados.save(new EventoProcessado(evento.eventoId()));
    }
}

