// Porta de saída (domínio)
public interface PedidoRepositoryPort {
    Pedido salvar(Pedido pedido);
}

// Caso de uso (domínio, sem dependência de framework)
public class FinalizarPedido {
    private final PedidoRepositoryPort pedidos;
    public FinalizarPedido(PedidoRepositoryPort pedidos) { this.pedidos = pedidos; }
    public Pedido executar(Pedido p) { p.finalizar(); return pedidos.salvar(p); }
}

// Adaptador (infraestrutura)
@Repository
class PedidoJpaAdapter implements PedidoRepositoryPort {
    private final PedidoJpaRepository jpa;
    public Pedido salvar(Pedido p) { return jpa.save(PedidoEntity.from(p)).toDomain(); }
}

